+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            font-family: 'Inter', sans-serif;
+        }
+        .game-container {
+            max-width: 600px;
+            padding: 28px;
+            border-radius: 20px;
+            background: rgba(15, 23, 42, 0.8);
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.35);
+        }
+        .score {
+            font-size: 24px;
+            font-weight: bold;
+            color: #F8FAFC;
+        }
+        .high-score {
+            font-size: 18px;
+            color: #F8FAFC;
+        }
+        .start-game {
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            font-size: 36px;
+            font-weight: bold;
+            color: #F8FAFC;
+            cursor: pointer;
+        }
+        .game-over {
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            font-size: 36px;
+            font-weight: bold;
+            color: #F8FAFC;
+            cursor: pointer;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <canvas id="game-canvas" width="400" height="400"></canvas>
+        <div class="score">Score: <span id="score">0</span></div>
+        <div class="high-score">High Score: <span id="high-score">0</span></div>
+        <div class="start-game" id="start-game">Start Game</div>
+        <div class="game-over" id="game-over" style="display: none;">Game Over! <span id="replay">Replay</span></div>
+    </div>
+    <script>
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [];
+        let food = {};
+        let direction = 'right';
+        let gameInterval;
+        let audioContext;
+        let soundSource;
+        
+        const gameCanvas = document.getElementById('game-canvas');
+        const ctx = gameCanvas.getContext('2d');
+        const startGameButton = document.getElementById('start-game');
+        const gameOverButton = document.getElementById('game-over');
+        const replayButton = document.getElementById('replay');
+        const scoreSpan = document.getElementById('score');
+        const highScoreSpan = document.getElementById('high-score');
+        
+        startGameButton.addEventListener('click', startGame);
+        replayButton.addEventListener('click', startGame);
+        document.addEventListener('keydown', handleKeydown);
+        
+        function startGame() {
+            score = 0;
+            snake = [{x: 200, y: 200}];
+            food = {x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10};
+            direction = 'right';
+            gameInterval = setInterval(updateGame, 100);
+            audioContext = new AudioContext();
+            soundSource = audioContext.createOscillator();
+            soundSource.type = 'sawtooth';
+            soundSource.frequency.value = 200;
+            soundSource.connect(audioContext.destination);
+            startGameButton.style.display = 'none';
+            gameOverButton.style.display = 'none';
+        }
+        
+        function updateGame() {
+            ctx.clearRect(0, 0, gameCanvas.width, gameCanvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(56, 189, 248, 0.5)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+            
+            if (direction === 'right') {
+                snake.push({x: snake[snake.length - 1].x + 10, y: snake[snake.length - 1].y});
+            } else if (direction === 'left') {
+                snake.push({x: snake[snake.length - 1].x - 10, y: snake[snake.length - 1].y});
+            } else if (direction === 'up') {
+                snake.push({x: snake[snake.length - 1].x, y: snake[snake.length - 1].y - 10});
+            } else if (direction === 'down') {
+                snake.push({x: snake[snake.length - 1].x, y: snake[snake.length - 1].y + 10});
+            }
+            
+            if (snake[snake.length - 1].x === food.x && snake[snake.length - 1].y === food.y) {
+                score++;
+                food = {x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10};
+                soundSource.frequency.value = 250;
+                soundSource.start();
+                setTimeout(() => soundSource.stop(), 100);
+            } else {
+                snake.shift();
+            }
+            
+            if (snake[snake.length - 1].x < 0 || snake[snake.length - 1].x >= gameCanvas.width || snake[snake.length - 1].y < 0 || snake[snake.length - 1].y >= gameCanvas.height) {
+                gameOver();
+            }
+            
+            for (let i = 0; i < snake.length - 1; i++) {
+                if (snake[i].x === snake[snake.length - 1].x && snake[i].y === snake[snake.length - 1].y) {
+                    gameOver();
+                }
+            }
+            
+            scoreSpan.textContent = score;
+            if (score > highScore) {
+                highScore = score;
+                localStorage.setItem('highScore', highScore);
+            }
+            highScoreSpan.textContent = highScore;
+        }
+        
+        function handleKeydown(event) {
+            if (event.key === 'ArrowUp' || event.key === 'w') {
+                if (direction !== 'down') {
+                    direction = 'up';
+                }
+            } else if (event.key === 'ArrowDown' || event.key === 's') {
+                if (direction !== 'up') {
+                    direction = 'down';
+                }
+            } else if (event.key === 'ArrowLeft' || event.key === 'a') {
+                if (direction !== 'right') {
+                    direction = 'left';
+                }
+            } else if (event.key === 'ArrowRight' || event.key === 'd') {
+                if (direction !== 'left') {
+                    direction = 'right';
+                }
+            }
+        }
+        
+        function gameOver() {
+            clearInterval(gameInterval);
+            soundSource.frequency.value = 100;
+            soundSource.start();
+            setTimeout(() => soundSource.stop(), 100);
+            gameOverButton.style.display = 'block';
+        }
+    </script>
+</body>
+</html>

